/**
 * The built-in drawings of space images (assets/space-covers, generated by tooling/space-covers) as key → URL.
 * `?no-inline` keeps every drawing a file of its own: at about 2 KB each Vite would otherwise inline all of them as
 * data URLs into the script that imports this map. So the eager bundle carries only the map, a drawing is fetched
 * when it is shown and cached for good under its hashed name; scripts/atlasBundle.mjs fails the build if one is
 * inlined after all. The only module with this glob: vite.config.ts keeps glob users out of vitest's module cache.
 */
const files = import.meta.glob<string>("./assets/space-covers/*.svg", { query: "?url&no-inline", import: "default", eager: true });
const urls = new Map(Object.entries(files).map(([path, url]) => [path.slice(path.lastIndexOf("/") + 1, -".svg".length), url]));

/** The static URL of a catalog drawing; undefined for a key this build does not ship. */
export const spaceCoverDrawingUrl = (key: string | null | undefined) => (key ? urls.get(key) : undefined);
export const spaceCoverDrawingKeys: readonly string[] = [...urls.keys()];
